<span class="line"><span style="color:#839496;">mem </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#93A1A1;font-weight:bold;">char</span><span style="color:#859900;"> *</span><span style="color:#839496;">)(((</span><span style="color:#93A1A1;font-weight:bold;">uintptr_t</span><span style="color:#839496;">)_mem </span><span style="color:#859900;">&amp;</span><span style="color:#859900;"> ~</span><span style="color:#839496;">(</span><span style="color:#93A1A1;font-weight:bold;">uintptr_t</span><span style="color:#839496;">)</span><span style="color:#859900;">0x</span><span style="color:#D33682;">fff</span><span style="color:#839496;">) </span><span style="color:#859900;">+</span><span style="color:#D33682;"> 2</span><span style="color:#859900;"> *</span><span style="color:#D33682;"> 4096</span><span style="color:#839496;">);</span></span>
